CREATE TABLE IF NOT EXISTS lab_user(id BIGINT PRIMARY KEY, username VARCHAR(40) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS device(id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS booking(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,device_id BIGINT NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'CONFIRMED',version INT NOT NULL DEFAULT 0,request_key VARCHAR(64) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_booking_request(user_id,request_key),KEY ix_booking_slot(device_id,status,start_at,end_at));
CREATE TABLE IF NOT EXISTS ticket(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,device_id BIGINT NOT NULL,title VARCHAR(100) NOT NULL,description TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',version INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ticket_event(id BIGINT PRIMARY KEY AUTO_INCREMENT,ticket_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,from_status VARCHAR(20) NOT NULL,to_status VARCHAR(20) NOT NULL,note VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY ix_ticket_event(ticket_id,id));
CREATE TABLE IF NOT EXISTS knowledge(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(100) NOT NULL,keywords VARCHAR(200) NOT NULL,content TEXT NOT NULL);
